const course: DeepCourse = {"slug":"real-estate-va","title":"Real Estate VA.","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Specialism · Pro</p><h1 class=\"display-lg mt-4\">Real Estate VA<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Keep an agent&#x27;s database honest, their leads answered in minutes, and their closings from falling apart in week three.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">8 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">5h 42m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">8 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">Real estate support is not one job, and pretending it is will cost you money. An admin VA, an inside sales assistant, a listing coordinator and a transaction coordinator do completely different work, get paid differently, and get fired for different reasons. The first thing this track makes you do is pick a lane.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">What ties all of them together is that agents are terrible at follow-through. They are good at talking to people and bad at the eleven days between a signed contract and a missed inspection deadline. You are being hired for the boring middle, and the boring middle is where the commission actually survives.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">Everything here runs on one fictional client: the Reyes Group, a three-agent team in Tampa with a Follow Up Boss account that has not been cleaned since 2023. You will fix their database, build their speed-to-lead system, launch a listing, run a contract-to-close board, and make a call report that tells the truth. Fictional addresses, fictional people, real workflow.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Also posted as</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">ISA, listing coordinator, transaction coordinator, real estate admin, acquisitions VA</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Core loop</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Lead in → responded fast → logged → nurtured → appointment → paperwork</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Hours</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Usually 20–40/wk, often anchored to one US time zone&#x27;s business hours</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Hardest part</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Being measured on deals you do not control</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Easiest way in</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">CRM cleanup and speed-to-lead response. Small, provable, immediately valuable.</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Shift start</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">New lead sweep</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Anything that came in overnight gets a first response now, not after your coffee. Minutes matter here more than anywhere else in VA work.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">First hours</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Follow-up queue</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">The CRM tells you who is due today. You work the list, log every touch, and set the next step before closing the record.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Midday</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Listing and transaction admin</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Photos scheduled, documents chased, deadlines checked against the contract dates.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Afternoon</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Database hygiene</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Duplicates, missing phone numbers, wrong stages, dead tags. An hour a day keeps the pipeline view honest.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Blocked block</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Outbound calling, if that is your seat</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Usually one or two dedicated days a week. Around 100 dials in a four-hour shift is a normal load.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Shift end</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Daily numbers</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Dials, connects, conversations, qualified leads, appointments set, and anything hot the agent has to touch tonight.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Do not buy anything yet. Learn the free ones properly and use the client&#x27;s licence for the rest — that is what everyone else is doing too.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">The CRM will be one of these</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Follow Up Boss</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The most common team CRM in US residential. Free official training and admin guides exist, so learn it properly.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">kvCORE / Lofty</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Brokerage-issued platforms with lead routing, smart campaigns and landing pages baked in.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">BoomTown / Top Producer / Wise Agent</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Older but everywhere. Same concepts: contacts, stages, tasks, campaigns.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">RESimpli / Podio</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Investor and wholesaler side. Deal pipelines rather than buyer/seller pipelines.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Property, calling and paperwork</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Zillow / Realtor.com / Redfin</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Public research you can do without MLS access. Good enough for most prep work.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">PropStream / BatchLeads / DealMachine</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Investor lead pulling and skip tracing. Know what the data actually is before you call it.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Mojo Dialer / Vulcan7</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Dialers for expired and FSBO campaigns. Learn dispositions, not just how to press call.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Dotloop / SkySlope / DocuSign</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Transaction platforms. Signature routing, document checklists, deadline tracking.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">AppFolio / Buildium</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Property management side. Maintenance tickets, tenant comms, rent ledgers.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Everything else you actually use daily</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Sheets</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Lead imports, dedupe, call reports, pipeline dashboards. This is half the job.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Canva</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Listing flyers, buyer packets, open house signage, social graphics.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Calendly</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Showing and consultation booking without twelve texts.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Loom</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Show the agent what you changed in the CRM instead of writing a paragraph they will not read.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://www.nar.realtor/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">National Association of Realtors</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The vocabulary source. If a term confuses you, search it here first.</p></a></li><li class=\"h-full\"><a href=\"https://www.followupboss.com/blog\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Follow Up Boss blog</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The CRM many US teams run. Their blog doubles as ISA training.</p></a></li><li class=\"h-full\"><a href=\"https://www.zillow.com/agent-resources/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Zillow agent resources</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">How US agents think about leads — useful context for the person you support.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Philippine market benchmarks for real estate VA work from OnlineJobs.ph&#x27;s April 2026 salary guide, with the wider overseas range from real estate outsourcing directories sitting around $5–$15/hr for specialised seats. These are observations, not a ceiling. Do not quote cold calling, CRM management, listing coordination and transaction coordination as one generic number, because they carry very different levels of responsibility.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Beginner</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">4–7<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:40%;width:30%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Data entry, lead entry, scheduling, basic CRM tasks under close direction.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 640–1,120/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Intermediate</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">6–8<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:60%;width:20%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Owns the follow-up queue and the database. Runs calling shifts and reports properly.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 960–1,280/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Expert</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">8–10<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:80%;width:20%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Transaction coordination, listing launches, ISA work with real qualification judgment.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,280–1,600/mo full-time</p></div></div></div><p class=\"mt-7 border-t border-line pt-4 text-[0.75rem] leading-relaxed text-muted-2\">Directional market benchmarks, not a guarantee and not a ceiling. Source: <a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">OnlineJobs.ph salary guide, April 2026</a>. Monthly figures assume 40 hours a week, which most VA roles are not.</p></div><div class=\"mt-5 rounded-2xl border border-[#f4d9c6] bg-clay-wash/70 p-6 sm:p-7\"><p class=\"eyebrow text-clay-deep\">What actually moves you up a band</p><ul class=\"mt-3.5 grid gap-2.5 sm:grid-cols-2\"><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You run transaction coordination, where a mistake costs a closing</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You know a named CRM deeply enough to configure it, not just use it</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You qualify leads instead of only logging them</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You cover the client&#x27;s business hours live, so speed to lead is real</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You produce reports that diagnose the campaign, not just count activity</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You built the SOPs the next VA is onboarded with</li></ul></div></section></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><figure class=\"rounded-2xl border border-line bg-card p-7 shadow-card sm:p-9\"><figcaption class=\"flex flex-wrap items-center gap-3\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">Worker story</span><span class=\"text-[0.8125rem] text-muted\">One person&#x27;s experience, not a universal rule</span></figcaption><h2 class=\"mt-4 font-display text-[1.5rem] font-semibold leading-snug text-ink\">100 calls a shift and a 2% expectation</h2><blockquote class=\"mt-5 border-l-2 border-clay pl-5 font-display text-[1.1875rem] italic leading-relaxed text-ink\">“Mostly &quot;not interested&quot;, &quot;we don&#x27;t live there&quot;, or a hang-up.”</blockquote><p class=\"mt-5 text-[0.9375rem] leading-relaxed text-ink-2\">A Filipino real estate VA posted on r/buhaydigital in 2026, unsure whether they were bad at the job. They were making around 100 cold calls per four-hour shift, hearing almost nothing but rejection, and their client had told them the expected success rate was about 2 percent. They later clarified that only one day a week was dedicated to calling, with the rest spent on email marketing, content, admin and monitoring the client&#x27;s Airbnb properties. One commenter who had made roughly 400 calls a day for two months said the client got two deals from it and considered that fine. Another argued that the lead source and data quality mattered far more than dialling harder.</p><div class=\"mt-5 rounded-xl border border-teal-pale bg-teal-wash/60 p-4\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The lesson</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The rejection rate is the job, not your performance review. What you owe the client is dials, adherence, honest logging and follow-through. What the client owes you is a decent list, a tested offer, a working script and their own follow-up. Report activity and outcomes separately from week one, and the conversation about whose problem it is never becomes personal.</p></div><a href=\"https://old.reddit.com/r/buhaydigital/comments/1m7ib37/im_a_real_estate_va_and_i_dont_know_whether_im/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-4 inline-block text-[0.8125rem] font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">Read the original thread — r/buhaydigital, 2026</a></figure></div><section id=\"first-client\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Getting the first one to say yes</h2><ol class=\"mt-7 space-y-4\"><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">01</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Pick the seat, then say it out loud</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">&quot;I do listing and transaction coordination for small teams&quot; gets read. &quot;Real estate virtual assistant, all tasks&quot; gets skipped, because the agent has to do the thinking.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">02</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Learn one CRM properly, for free</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Follow Up Boss publishes admin guides, help docs and a short bootcamp. Work through them, screenshot your own trial or demo setup, and put the platform name in your headline.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">03</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Lead with the cleanup offer</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">&quot;I&#x27;ll audit and deduplicate your database and show you how many enquiries from the last 90 days were never called back, fixed price, one week.&quot; It is small, it is provable, and the finding usually terrifies them into hiring you properly.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">04</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Apply to the adjacent titles</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Transaction coordinator, listing coordinator, ISA, acquisitions assistant, real estate admin, property management assistant. Filtering only for &#x27;real estate VA&#x27; hides most of the good roles.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">05</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Go where agents complain</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Agent Facebook groups, brokerage communities, r/realtors. Not to pitch, to answer questions about CRMs and coordination. The referrals in this industry are relentless once you are in.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">06</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Never take deal-only pay for hourly work</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Commission arrangements can be legitimate, but not as a substitute for paying you for 20 hours a week of admin and calling on a list you did not choose.</p></div></li></ol><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">What goes in the portfolio</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">Every one of these comes out of the exercises above. Finish the track and you have the folder, not just the knowledge.</p><ul class=\"mt-5 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">CRM cleanup log, before and after</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Instantly legible, and the &#x27;never called back&#x27; number sells the whole engagement.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Speed-to-lead SOP</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Shows you understand the one metric that separates good real estate support from admin.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Two five-touch nurture sequences with real copy</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Proves you can write to a stranger without sounding like a bot.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Listing intake form and launch timeline</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Reads like a coordinator, prices like a coordinator.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Contract-to-close tracker with a deadline collision flagged</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">The single best proof that you notice risk rather than just typing dates.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Weekly call report with activity and outcome split</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Signals that you protect yourself with data, which experienced agents respect.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Escalation rules page</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Tells an agent exactly how much supervision you need, which is the thing they are secretly worried about.</p></li></ul></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one of these is a scam. Some are just clients who will cost you more than they pay you, which ends the same way.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Asks you to give pricing, legal, tax or negotiation advice</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">That is licensed work. If it goes wrong the exposure lands on the brokerage and, informally, on you.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Wants you calling a list they cannot confirm was DNC-scrubbed</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Compliance is theirs, but you are the voice on the recording. Get the confirmation in writing before the first dial.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>&quot;Use your own phone number for the outbound campaign&quot;</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Your personal number ends up on spam lists and complaint filings. Use a client-provided line.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Pay tied to closed deals for admin or calling hours</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You do not control the list, the offer, the market or whether the agent follows up. Do not accept the risk of things you cannot influence.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Any request touching escrow, earnest money or wiring instructions</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Real estate wire fraud is a multi-million dollar problem. A VA never sends, confirms or changes payment details.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Shares the brokerage MLS login with you</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Usually a rules violation. Ask for proper assistant access instead, and note that a client casual about this will be casual about your pay too.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Blames you for zero deals while refusing to fix the data or script</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">The clearest sign of a client you will never satisfy. Report the diagnosis once, then start looking.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>No approved script and no escalation path</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You will be improvising in a regulated industry on someone else&#x27;s behalf. Get both documented before you start.</p></li></ul></section></div><section id=\"faq\" class=\"scroll-mt-32 border-t border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><div class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Do I need a real estate licence?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Not for admin, coordination, marketing or follow-up under an agent&#x27;s direction. You do need one to advise on price, negotiate terms, or represent a party. The safest habit is to prepare everything and hand the decision to the licensed person, which also makes you look more professional, not less.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Is cold calling unavoidable in this niche?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">No. Listing coordination, transaction coordination, CRM management and marketing are all real seats with no dialling. Calling roles are the easiest to get hired into and the fastest to burn out of, so know which trade you are making.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">I have never used Follow Up Boss. Can I still apply?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Yes, if you have done the free official training and can screenshot a setup you built in a trial or demo. CRMs are conceptually identical: contacts, stages, tasks, campaigns, reporting. Say which one you know and that you can learn theirs in a week, then prove it with your own pipeline screenshots.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">What if the client&#x27;s leads are garbage and I look bad?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Report activity and outcomes separately from your very first week, before there is any tension. When the numbers go badly, the disposition breakdown does the arguing for you and nobody has to be accused of anything.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How do I build a portfolio without touching real client data?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Fictional addresses, fictional names, invented but consistent numbers, and a clear label on every file saying it is simulated. Nobody expects you to leak a real database, and a client who wants to see one is telling you something about how they will treat yours.</p></details></div><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">Where the facts in this course came from</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">All free, all worth your time. Open them in another tab and check us.</p><ul class=\"mt-5 space-y-2.5\"><li><a href=\"https://help.followupboss.com/hc/en-us/articles/4414062131863-Follow-Up-Boss-Training-Resources\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Follow Up Boss training resources</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Official admin guides, help docs, daily training and a short bootcamp. Free, and the platform name is worth having on your profile.</span></a></li><li><a href=\"https://www.followupboss.com/blog/use-real-estate-virtual-assistant-grow-business\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Follow Up Boss: how agents use a real estate VA</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">A clear breakdown of the duty categories, written for the person hiring you. Read it to learn their vocabulary.</span></a></li><li><a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">OnlineJobs.ph salary guide</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The April 2026 PH benchmark, including a real estate VA row.</span></a></li><li><a href=\"https://www.virtualassistantassistant.com/real-estate-services\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Virtual Assistant Assistant: real estate services</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Useful for seeing what agencies charge clients, which is the ceiling your rate is negotiating against.</span></a></li><li><a href=\"https://old.reddit.com/r/buhaydigital/comments/1m7ib37/im_a_real_estate_va_and_i_dont_know_whether_im/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">r/buhaydigital real estate VA thread</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The worker story above, in full, with the comment thread arguing about call volume versus data quality.</span></a></li></ul></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-16\"><div class=\"rounded-2xl border border-line bg-clay-wash/60 p-7 sm:p-9\"><h2 class=\"font-display text-[1.5rem] font-semibold text-ink\">Finished? Go and use it.</h2><p class=\"mt-3 max-w-lg text-[0.9375rem] leading-relaxed text-ink-2\">The board updates every 30 minutes. Filter for this specialism, check your number against the rate tool, and send five tailored applications rather than fifty copy-pasted ones.</p><div class=\"mt-6 flex flex-wrap gap-3\"><a class=\"btn btn-primary\" href=\"/jobs\">See jobs on the board</a><a class=\"btn btn-ghost\" href=\"/pricing-tool\">Check your rate</a></div></div><div class=\"mt-10\"><p class=\"eyebrow text-muted\">Other written tracks</p><ul class=\"mt-3 flex flex-wrap gap-2.5\"><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/executive-assistant\">Executive Assistant</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/seo-specialist\">SEO Specialist VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/social-media-manager\">Social Media Manager VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/ecommerce-va\">E-commerce VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/complete-va-starter\">The Complete VA Starter</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/applications-that-get-replies\">Applications That Get Replies</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/pricing-and-negotiation\">Pricing &amp; Negotiation</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/becoming-an-ops-lead\">Becoming an Operations Lead</a></li></ul></div><a class=\"btn btn-ghost mt-8\" href=\"/courses\">← All courses</a></div><!--$--><!--/$-->"}],"modules":[{"n":1,"title":"The industry map and where you legally sit","outcome":"You can name every seat on a real estate team, say which one you are applying for, and draw the line between admin support and licensed advice.","badges":["Rates","Red/green flags"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Agent, broker, investor, wholesaler, property manager. Four of those five make money in completely different ways, and it changes what they will ask you to do.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Inside the team there are seats: ISA chases and qualifies leads, listing coordinator gets a property to market, transaction coordinator gets a signed contract to closing, admin VA holds the database and calendar together.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You can gather, organise, schedule, follow up, prepare documents and communicate under the agent&#x27;s direction. You cannot price a home, interpret a contract, advise on tax or negotiate terms. That is licensed work and the licence is not yours.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Compliance is not optional decoration. Do-not-call rules, TCPA restrictions on autodialling and texting, MLS access rules and brokerage policy all vary by market and your client is responsible for telling you theirs, in writing.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never share or use MLS credentials casually. If the client wants MLS work done, ask whether their brokerage allows assistant access and get it set up properly.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pick your lane before you apply. &quot;Real estate VA&quot; is a rate-lowering phrase. &quot;Transaction coordination for a three-agent team&quot; is a job with a number attached.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Same request, three different answers</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Agent: &quot;Just tell the buyer what you think the house is worth, you&#x27;ve seen the comps.&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Agent: &quot;Look at the contract and tell them if the repair request is reasonable.&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Agent: &quot;Can you text this list of 400 numbers about our new listing?&quot;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;I&#x27;ve pulled three comparable sales and put them in a sheet for you. Sending it now so you can give them the number.&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;I&#x27;ve highlighted the repair clause and the response deadline, it&#x27;s Thursday 5pm. Your call on what&#x27;s reasonable, I&#x27;ll send whatever you decide.&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;Before I send, can you confirm these were scrubbed against DNC and that they&#x27;ve opted in? I&#x27;ll do it the moment you confirm in writing.&quot;</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">You never said no. You did the work up to the legal line and handed the decision back with everything ready. That reads as senior, not difficult.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What real estate VA work pays</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Real estate pays above general admin because mistakes are expensive and deadlines are legal. The jump from admin to transaction coordination is the biggest single pay step available to you in this niche.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Entry — admin / data entry</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$4–6</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$650–1,000</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">CRM cleanup, listing data, scheduling. No client contact.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Junior — listing + marketing coordinator</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$6–8</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,000–1,300</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You run listings end to end and produce the marketing.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Mid — ISA (inside sales agent)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$7–11 + bonus</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,150–1,800 + $25–100/appt</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You call leads and set appointments. Bonus structure is where the real money is.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Senior — transaction coordinator</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$9–14</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,500–2,300</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own contract-to-close. Deadline discipline is the entire skill.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Lead — ops manager for a team</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$13–20</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,100–3,200</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You run the CRM, the other VAs and the reporting for a whole brokerage team.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><div class=\"mt-4\"><p class=\"eyebrow mb-2 text-muted\">Same skill, different client</p><ul class=\"grid gap-2 sm:grid-cols-2\"><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Verse&#x27;s job board (median)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$5.40</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Across live real estate listings. Above the general VA median of $3.50.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Per-transaction TC work</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$250–500 per closed file</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">How experienced TCs actually price. A good one runs 15–25 files a month.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">ISA with appointment bonus</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$6–9 base + $25–100/appt</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Base plus bonus beats a flat rate once you&#x27;re good. Negotiate for the bonus.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">US client, direct</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$7–15</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">The overwhelming majority of this market. Expect to work US hours.</p></li></ul></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Sources: Verse&#x27;s live board (n=2,081), OnlineJobs.ph real estate tiers, and US TC per-file rate norms. Real estate VAs work US timezones almost without exception — price the graveyard shift in.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A lead asks you a question on a call</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Based on what I&#x27;m seeing in the area, I&#x27;d say your house is worth about $450,000 and honestly you should list now before rates go up.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">That is a valuation and it is advice about a transaction. In most US states, doing that without a licence is illegal and it exposes your agent&#x27;s licence, not just you. It is the fastest way to end this career.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I can&#x27;t give you a value — I&#x27;m not licensed and I&#x27;d be doing you a disservice by guessing. What I CAN do is get [Agent] on the phone with you, and she does a proper comparative market analysis for free. She has Thursday at 2 or Friday at 10 — which works?&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Names the boundary honestly, doesn&#x27;t apologise for it, and converts the moment into an appointment. Your job is to route to the licensed person, and doing it confidently makes you sound more professional, not less.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The job post says</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Real estate VA needed. Cold call 300 numbers/day from our list, must have own dialer, commission only, unlimited earning potential! Will train the right person.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Commission only means you carry all the risk and they carry none. 300 dials a day with no base is a churn model — they expect you to quit and they&#x27;ll hire another one next month.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;ISA for our 4-agent team. 100–150 dials/day from our CRM (we supply the dialer and the list). $7/hr base + $50 per appointment that shows. 30 hrs/wk, 8am–2pm EST. Scripts and 2 weeks&#x27; paid training provided.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">A base you can live on, a bonus that rewards the outcome, realistic dial volume, they supply the tools, and paid training. This is a team that intends to keep you.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Find eight live real estate VA job ads across OnlineJobs.ph, Upwork and LinkedIn. Sort them by which seat they are actually hiring for, ignoring the title.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A table of eight ads with the real seat, the tools named, the hours, the rate, and one line on whether the scope is defined or a grab bag.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every row names the seat, not the ad title</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You flagged at least two ads that bundle three seats into one salary</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You noted which CRM appears most often</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You picked one seat to specialise in and wrote one sentence saying why</span></label></li></ul></div>"},{"n":2,"title":"CRM hygiene and the pipeline nobody trusts","outcome":"You can take an eight-thousand-record database full of duplicates and hand back a pipeline the agent will actually open every morning.","badges":["Workflow","Tools","Time split"],"minutes":40,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A dirty database is not a cosmetic problem. Agents stop trusting the CRM, work from memory instead, and then wonder why leads evaporate.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Clean in this order: deduplicate, then fix required fields, then fix stages, then tags, then archive the dead. Tagging a duplicate twice just makes two wrong records.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Match duplicates on phone and email first, name last. Two people are called Maria Santos. One phone number is one human.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Stages must be mutually exclusive and defined in one sentence each. If two people on the team disagree about what &quot;warm&quot; means, the pipeline number is fiction.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Tags describe attributes, stages describe progress. Buyer, Seller, Investor, 33606, First-time, Sphere are tags. New, Attempted, Contacted, Appointment Set, Under Contract, Closed, Nurture, Dead are stages.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never bulk-edit without a backup export first. Export, edit a copy, verify a sample of twenty, then import. A bad merge in a CRM is not always reversible.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every record needs a next step with a date, or it is not in a pipeline, it is in a graveyard.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Reyes Group database, before and after</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">8,214 records, 1,190 with no phone number</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">412 obvious duplicates (same mobile, three spellings of the name)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Stages in use: New, new lead, Hot, HOT!!, warm, Warm lead, Nurture, nurture, Closed, Past client, Dead, DNC, blank (2,900 records)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Tags: 268 distinct, including &#x27;zillow&#x27;, &#x27;Zillow&#x27;, &#x27;ZIllow lead&#x27;, &#x27;z&#x27;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Last activity older than 12 months: 5,100 records</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">6,940 records after merging 412 duplicates and archiving 862 with no contact method at all</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">8 stages, each defined in one sentence in a pinned doc</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">31 tags, controlled list, source tags standardised to Zillow / Realtor.com / Open House / Sphere / Referral / Cold List</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Every active record has an owner and a next-step date</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">5,100 stale records moved to a Long Nurture stage on a quarterly email, not deleted</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Backup export saved before every bulk action, dated, in a shared Drive folder</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The number that sells this to the agent is not 6,940. It is &quot;you have 214 people who enquired in the last 90 days and were never called back&quot;. Always find that number.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Weekly CRM cleanup</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same time every week. A CRM nobody trusts is worse than no CRM.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Find and merge duplicates</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Search by phone number first, then email, then name. Phone catches the most. Merge, never delete — you&#x27;ll lose the history.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Fix every record with no next action</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A lead with no task and no date is a lead that&#x27;s gone. Either give it a next step or move it to a nurture list on purpose.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Audit the stages</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Anything sitting in the same stage for 30+ days is lying to you. Either it moved and nobody logged it, or it&#x27;s dead.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Fix the bad data</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Missing phone numbers, dead emails, no lead source. Lead source matters most — it&#x27;s how the agent decides where to spend money.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Tag consistently</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Agree the tag list once and never freelance new ones. &quot;Buyer-Hot&quot;, &quot;buyer hot&quot; and &quot;HOT BUYER&quot; are three tags and none of them work.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Send the one-page pipeline summary</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Counts per stage, what moved, what went stale, what needs the agent. This is the deliverable — the cleanup is just the work behind it.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Cleaning silently. If you fix 400 records and don&#x27;t report it, the agent thinks you did nothing that week. Always send the before/after count.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Real estate CRMs and tools</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">You will not choose the CRM — the agent already has one. Learn the concepts (stages, tasks, drips, smart lists) and any of them takes a week to pick up.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Follow Up Boss</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Teams that take lead follow-up seriously. The most VA-friendly of them.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a few days</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$69+/user/mo (client pays)</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The one most worth learning first. Clean UI, brilliant smart lists, and it&#x27;s named in a lot of job posts.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">kvCORE / BoldTrail</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Big brokerages. Website + CRM + IDX in one.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — bloated</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Brokerage-provided</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Clunky, but enormous market share. Knowing it is a genuine differentiator because most VAs avoid it.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Chime / Lofty</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Teams that want AI lead scoring and built-in dialing.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$500+/mo team</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Growing fast. Worth a free trial walkthrough so you can say you&#x27;ve used it.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Sierra Interactive</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">High-volume lead gen teams.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$500+/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Strong reporting. Less common, but the teams using it tend to pay above market.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Dotloop / SkySlope</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Transaction management and e-signatures.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a day</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Brokerage-provided</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Learn one of these the moment you touch transaction coordination. This is where the deadline discipline lives.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Canva + CloudCMA</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Listing flyers and comparative market analysis packets.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$10/mo + $30/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">CloudCMA does in 3 minutes what agents spend an hour on. Offering this makes you instantly useful.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Where a full-time real estate VA&#x27;s week goes</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">40 hrs/week supporting a small team with 3 active listings and 8 deals in the pipeline.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b2lanpfiuqbtb_\"><title id=\"_R_b2lanpfiuqbtb_\">Lead follow-up: calls, texts, emails 28%, Transaction coordination 22%, CRM hygiene and data entry 16%, Listing coordination and marketing 15%, Scheduling: showings, inspections, closings 11%, Reporting and agent comms 8%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"98.52034561657592 253.3380315854809\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"77.4088429844525 274.4495342176043\" stroke-dashoffset=\"-98.52034561657592\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"56.297340352329094 295.5610368497277\" stroke-dashoffset=\"-175.92918860102844\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"52.778756580308524 299.0796206217483\" stroke-dashoffset=\"-232.22652895335753\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#4453b8\" stroke-width=\"20\" stroke-dasharray=\"38.70442149222625 313.1539557098306\" stroke-dashoffset=\"-285.00528553366604\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#c3e6df\" stroke-width=\"20\" stroke-dasharray=\"28.148670176164547 323.70970702589227\" stroke-dashoffset=\"-323.70970702589227\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Lead follow-up: calls, texts, emails</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">28%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The revenue engine. Most agents are terrible at it, which is why they hire you.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Transaction coordination</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">22%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Deadline chasing. Lumpy — quiet until three deals go under contract at once.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">CRM hygiene and data entry</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">16%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Boring, constant, and the foundation everything else stands on.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Listing coordination and marketing</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">15%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Photos, MLS entry, flyers, social. Burst of work per new listing.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#4453b8\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Scheduling: showings, inspections, closings</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">11%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Constant small interruptions. Batch where you possibly can.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#c3e6df\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Reporting and agent comms</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">8%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The daily huddle note. Small effort, keeps you employed.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Half the week is follow-up and CRM. Agents think they&#x27;re hiring you for marketing; they&#x27;re actually hiring you because nobody called the lead back.</p></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build a messy 120-row lead sheet yourself with deliberate duplicates, inconsistent casing, missing phones and eleven versions of four stages. Then clean it in a copy.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Two tabs, Before and After, plus a short cleanup log listing every rule you applied and how many records each rule touched.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 80 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Duplicates matched on phone and email, not name</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">A controlled list of stages with one-sentence definitions</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Source tags standardised to a fixed set</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Nothing deleted, only archived, and you can say why</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The log states the one number an agent would care about</span></label></li></ul></div>"},{"n":3,"title":"Speed to lead and follow-up that does not die at touch two","outcome":"You can build and run a five-touch follow-up sequence, and respond to a new enquiry fast enough to actually matter.","badges":["Workflow","2 templates"],"minutes":38,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Speed to lead is the gap between an enquiry and a real human response. Minutes beat hours by an embarrassing margin, and this is the single easiest thing for a VA to be excellent at.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">First response is short and asks one question. Not a brochure. &quot;Hi Dana, saw your enquiry on 412 Palmetto. Are you looking to move in the next 90 days or just starting to look?&quot;</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Classify on first contact: buyer, seller, investor, renter, or not a real lead. Timeline, financing status and motivation are the three things you are listening for.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Most leads die because nobody touched them a fourth time. Build the sequence, put it in the CRM as tasks, and work the queue even when it feels pointless.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Log every attempt with a disposition code, even the no-answers. An unlogged call did not happen, and the pattern in the dispositions is what tells the agent their list is bad.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Escalate hot immediately by whatever channel the agent reads fastest, and agree what &quot;hot&quot; means before you start. Usually: ready in 30 days, pre-approved, or asking to see a specific property.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never leave a record without a next step. Even Dead gets a date if the reason was timing.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A five-touch sequence for a Zillow buyer lead</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">T+0 (within 5 min) — Call. No answer, leave a 12-second voicemail. Then text: &quot;Hi Dana, Marco&#x27;s assistant at Reyes Group, calling about 412 Palmetto. Are you free for a quick 2 min today?&quot;</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">T+0 (+1 hr) — Email with the listing link, three similar homes, and one question about timeline. No attachments, no PDF brochure.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">T+1 day — Call at a different time of day than touch one. People are habitual.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">T+3 days — Text with a genuinely useful item: a new listing in their price band, or a price drop on the one they viewed.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">T+7 days — Call, then a break-up email: &quot;Are you still looking, or should I stop filling your inbox?&quot; This one gets replies.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">No response after touch five — move to Long Nurture, monthly market email, revisit in 90 days.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Vary the channel and the time of day. Five calls at 2pm on the same phone number is one touch repeated five times.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Speed to lead: the first five minutes</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A new internet lead hits the CRM. The clock starts immediately.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Call within 5 minutes. Not 30. Five.</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Conversion drops off a cliff after the first few minutes — the lead is on three other sites right now. Whoever calls first usually wins, regardless of who&#x27;s better.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">If no answer, text immediately — before you leave a voicemail</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Text open rates crush voicemail. &quot;Hi [name], [agent]&#x27;s office — you just looked at [address]. Is that the one you&#x27;re after, or shall I send similar?&quot;</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Then voicemail, then email</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">All three within the first ten minutes. Different channels, same short message. You&#x27;re trying to be present, not persistent yet.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Log the attempt with a disposition code</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Every single time. An untracked call did not happen as far as the agent is concerned.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Set the next touch before you close the record</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Never leave a lead without a scheduled next action. This is the rule that separates working CRMs from graveyards.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Run the full cadence — 8+ touches over 30 days</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Most agents stop at touch two. The majority of conversions happen between touch four and eight. This gap is your entire value.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Giving up after two attempts because it feels like pestering. It isn&#x27;t — they asked to see a house. Stop only when they say stop, and then honour it instantly and permanently.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The 30-day follow-up cadence</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Build this as an automation, but check it manually. A lead who replies to a drip and gets another drip will never talk to you again.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>NEW INTERNET LEAD — 30 DAY CADENCE\n\nDAY 0 (within 5 min)\n  Call 1 → no answer → Text immediately → Voicemail → Email\n  Text: &quot;Hi [name], this is [you] with [agent]&#x27;s office. You just looked at [address] — is that the one, or want me to send a few similar? Happy to help either way.&quot;\n\nDAY 0 (evening, if no response)\n  Call 2 — different time of day. Morning leads answer in the evening.\n\nDAY 1\n  Text: &quot;Morning [name] — sent over 3 homes like [address] to your email. Any of them close?&quot;\n  Email: 3 handpicked listings. Not an automated blast. Handpicked, with one line each on why.\n\nDAY 3\n  Call 3 + text\n  Text: &quot;Quick one [name] — are you still looking, or did you find something? Totally fine either way, just don&#x27;t want to keep bothering you.&quot;\n  (This &quot;permission to leave&quot; text gets more replies than anything else in the cadence.)\n\nDAY 7\n  Value email — no ask. Neighbourhood report, price trend, &quot;3 homes that just dropped in price&quot;.\n\nDAY 12\n  Call 4 + text\n\nDAY 18\n  Text: &quot;[name], last one from me for a while. If timing&#x27;s off, no problem — want me to just send new listings in [area] once a week?&quot;\n\nDAY 25\n  Value email\n\nDAY 30\n  Call 5. Then move to long-term nurture: monthly market email, quarterly call.\n\nRULES\n• The moment they REPLY, all automation stops and it becomes a human conversation\n• Stop instantly if they say stop. Tag &quot;Do Not Contact&quot; and mean it.\n• Vary the time of day. Five calls at 10am is one call, repeated.\n• Log every touch with a disposition code, no exceptions</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">First-contact text scripts</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Short, human, easy to reply to. Never send a paragraph as a first text.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>NEW LEAD, PROPERTY-SPECIFIC\n&quot;Hi [name], [you] here from [agent]&#x27;s office — you just checked out [address]. Is that the one you&#x27;re after, or want me to send similar? Either way, happy to help.&quot;\n\nNEW LEAD, GENERAL SEARCH\n&quot;Hi [name] — [you] with [agent]. Saw you were browsing homes in [area]. What&#x27;s the timeline you&#x27;re working with?&quot;\n\nNO RESPONSE, DAY 3 (the permission-to-leave text)\n&quot;Hi [name] — still looking, or did you find a place? Genuinely fine either way, I just don&#x27;t want to keep texting you if you&#x27;re sorted.&quot;\n\nSELLER LEAD\n&quot;Hi [name], [you] from [agent]&#x27;s office. You asked about your home&#x27;s value on [site]. [Agent] does a proper walkthrough valuation free — takes about 20 min. Want me to find a time this week?&quot;\n\nREVIVING AN OLD LEAD\n&quot;Hi [name] — [you] from [agent]&#x27;s office, we spoke back in [month] about [area]. Prices there have moved [up/down] about [n]% since. Want me to send an update, or has your situation changed?&quot;\n\nRULES\n• Under 300 characters, always\n• One question, at the end\n• Use their first name once. Not three times.\n• No links in the first text — links look like spam and get filtered\n• Never text before 8am or after 8pm in THEIR timezone. This is a legal issue in the US, not a politeness one.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write the speed-to-lead SOP for the Reyes Group and the full five-touch sequence for two lead types: an online buyer enquiry and an expired listing seller.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: One SOP page plus two sequences with exact copy for every touch, and a disposition code list.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 70 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The SOP states a target response time and what to do when you are offline</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every touch names the channel, the timing, and the exact words</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Channels and times of day vary across the five touches</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a defined escalation rule for a hot lead</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The disposition list has at most ten codes and none of them overlap</span></label></li></ul></div>"},{"n":4,"title":"Listing coordination","outcome":"You can take a signed listing agreement and get the property live, accurate and marketed without the agent chasing you once.","badges":["Workflow","2 templates"],"minutes":36,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Listing coordination is a checklist job, and that is a compliment. The value is that nothing is missed, not that anything is clever.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Intake first: property details, seller contact and availability, occupancy, lockbox and access, HOA info, disclosures, existing survey or floor plan, and what the seller does not want photographed.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Media is the long pole. Photographer booking depends on the seller preparing the house, which depends on you giving them a prep list a week out.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Proof the listing like it is going to be screenshotted. Address, price, bed and bath count, square footage, lot size, year built, taxes, HOA fees, school district, and every link.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Fair housing language is a real risk. Describe the property, never the buyer. &quot;Great for families&quot;, &quot;safe neighbourhood&quot;, &quot;walking distance to church&quot; are the kind of phrases that create complaints.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build a launch timeline backwards from go-live: sign, intake, prep list, photos, copy draft, agent approval, MLS input, syndication check, social and email, open house.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">After go-live, check the listing on the public portals within 24 hours. Syndication mangles photos and drops fields constantly.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Listing launch timeline, 412 Palmetto Ave</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 0 — Listing agreement signed. Intake form sent to seller same day, access details confirmed.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 1 — Prep list to seller with photo-day checklist. Photographer booked for Day 5, 9am, confirmed in writing.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 2 — Disclosures and HOA docs requested. Copy drafted from intake, sent to agent for approval.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 4 — Seller confirms house ready. Agent approves copy with two edits.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 5 — Photos shot 9am, delivered 6pm. Selected 28, ordered hero first, floor plan attached.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 6 — MLS input, QA pass against the intake form, agent signs off. Flyer, buyer packet and social graphics built in Canva.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 7 — Live at 8am. Portal check at 5pm: Zillow dropped the floor plan, re-uploaded. Email to sphere sent, open house set for Day 10.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Day 8 — Showing feedback form live, feedback requests automated after every showing.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Nothing here is difficult. Doing all of it, in order, every single time, is what an agent is paying for and almost never gets.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">New listing, from signed agreement to live</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The listing agreement is signed. You typically have 5–7 days.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Open the file and build the checklist first</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Before anything else. Every listing runs the same 20 steps — never work from memory.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Book photography, and book it around the light</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Confirm what the seller must do first: declutter, lights on, cars off the drive, pets away. Send that list the day you book, not the day before.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Gather the property data while you wait for photos</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Square footage, lot size, year built, taxes, HOA fees, school district, disclosures. Every number gets a source. Never estimate.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Write the MLS description and get it approved</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Agent approves the copy AND the price before anything is entered. Get it in writing.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Enter into MLS carefully, then proof it twice</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">One wrong digit in the price or the square footage is a legal problem, not a typo. Read it back against the source document line by line.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Launch everywhere at once</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">MLS live → syndication check (Zillow, Realtor.com) → flyer → social → email to the database → just-listed postcards. Same day.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Publishing the MLS listing before the photos are ready. The first 72 hours on market generate the most views a listing will ever get, and burning them on a phone snapshot of a dark living room costs the seller real money.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Listing launch checklist</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Copy this per listing. Do not work from memory — this is the document that makes you look senior.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>LISTING: [address]\nAgent: [name] | Listed: [date] | Price: $[n] | MLS#: [n]\n\nPRE-LAUNCH\n[ ] Listing agreement signed, saved to [drive folder]\n[ ] Seller disclosures received and complete\n[ ] Property data verified against tax records: sq ft, lot, year, beds/baths\n[ ] HOA info: fee, what it covers, contact\n[ ] Photographer booked — [date/time], confirmed with seller\n[ ] Seller prep list sent [date] (declutter, lights, cars, pets)\n[ ] Floor plan / video / drone booked if applicable\n[ ] Lockbox + sign ordered and installed\n[ ] Showing instructions confirmed with seller (notice required, pets, alarm code)\n\nCOPY\n[ ] MLS description drafted — [n] characters, no fair-housing violations\n[ ] Agent approved description IN WRITING\n[ ] Agent approved price IN WRITING\n[ ] Headline and first line written for portals\n\n⚠ FAIR HOUSING — never describe the PEOPLE, only the PROPERTY\nBanned: &quot;family neighbourhood&quot;, &quot;walking distance to church&quot;, &quot;great for young couples&quot;,\n&quot;safe area&quot;, &quot;no kids&quot;, &quot;perfect for a growing family&quot;, &quot;exclusive&quot;, any mention of\nrace, religion, nationality, disability, family status.\nSafe: describe rooms, features, distances in miles, school DISTRICT (not quality).\n\nGO LIVE\n[ ] MLS entered — proofread twice against source docs\n[ ] Photos uploaded, correct order (exterior first, then main living, kitchen, beds)\n[ ] Syndication checked live on Zillow / Realtor.com / Redfin — verify, don&#x27;t assume\n[ ] Flyer designed and delivered to the property\n[ ] Social posts scheduled: IG, FB, agent&#x27;s personal\n[ ] Just-listed email to the database\n[ ] Neighbours / farm area notified\n[ ] Listing added to CRM with the seller as a contact\n[ ] Showing feedback form set up\n\nWEEKLY WHILE ACTIVE\n[ ] Showing feedback collected and summarised to the seller\n[ ] Views/saves pulled from the portals\n[ ] Price/activity report to seller every [n] days\n[ ] Photos refreshed if it sits past [n] days</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Seller weekly update</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Sellers get anxious and then they get angry. A predictable weekly note prevents almost every difficult conversation.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[Address] — week [n] update\n\nACTIVITY\nShowings this week: [n] (total: [n])\nOnline views: [n] on Zillow, [n] on Realtor.com\nSaves/favourites: [n]\n\nWHAT BUYERS SAID\n• [Direct feedback, including the unflattering bits]\n• [Direct feedback]\n• [Direct feedback]\nCommon theme: [the honest pattern — &quot;three of four mentioned the kitchen dated&quot;]\n\nTHE MARKET AROUND YOU\n[n] similar homes listed in [area] this week at $[range]\n[n] went under contract, average [n] days on market\nYour position: [honest read]\n\nWHAT WE&#x27;RE DOING NEXT WEEK\n• [Specific action]\n• [Specific action]\n\n[Agent] will call [day] to talk through [the decision, if there is one — price, staging, timing].</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Invent a property at a fictional address. Build the full listing intake form, the seller prep list, the launch timeline and a QA checklist, then write the listing description twice: once badly, once correctly.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Intake form, prep list, timeline, QA checklist, and the two descriptions with the fair housing problems annotated in the bad one.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 75 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The intake form captures access, occupancy and HOA</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The timeline runs backwards from go-live with named owners</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The QA checklist includes numbers, links and compliance language</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The bad description contains at least three annotated fair housing risks</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a post-launch portal verification step</span></label></li></ul></div>"},{"n":5,"title":"Contract to close without a heart attack","outcome":"You can run a transaction board that tracks every deadline and document, and escalate the right things to the agent before they become problems.","badges":["Workflow","Red/green flags","2 templates"],"minutes":38,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The moment a contract is signed, a clock starts on four or five dates: earnest money, inspection, appraisal, financing contingency, and closing. Miss one and someone loses money or leverage.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build the timeline from the contract&#x27;s effective date on day one. Every deadline goes on the board, in the calendar, and in the client&#x27;s CRM. Three places, because one of them will be ignored.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You track deadlines. You do not interpret them. &quot;Inspection objection deadline is Tuesday 5pm and we have not received the report&quot; is your job. &quot;We should ask for a credit&quot; is not.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Chase documents on a schedule, not a feeling. Two business days before a deadline, then the morning of. Polite, specific, one ask per message.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep a single status line per deal that anyone can read in five seconds: address, stage, next deadline, what is blocking, who owes what.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never touch escrow or earnest money. You confirm it was received and receipted by the correct party. You do not handle, move, or hold funds.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Wire fraud is the nightmare in this industry. Never send wiring instructions, never confirm them by email, and treat any change to payment details as fraud until the agent verifies by phone on a known number.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — One deal, one status line, updated daily</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">412 Palmetto — under contract, waiting on stuff</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">412 PALMETTO AVE — Under contract, closing 12 Sep</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Next deadline: Inspection objection, Tue 26 Aug 5:00pm ET</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Received: contract (14 Aug), EMD receipt (16 Aug), seller disclosures (17 Aug)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Outstanding: inspection report (buyer&#x27;s TC, chased 22 Aug and 25 Aug), HOA estoppel (ordered 18 Aug, 10-day turnaround, due 28 Aug)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Risk: HOA estoppel due 2 days before financing contingency. Flagged to Marco 22 Aug, he is calling the HOA.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Nothing needed from seller this week.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The Risk line is the whole reason a coordinator gets paid more than a data entry VA. You are being paid to notice the collision before it happens.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Contract to close</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Offer accepted. From here everything is a deadline and every deadline has a consequence.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Build the deadline calendar the same day</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Read the contract, extract every date, work backwards. Earnest money, inspection, appraisal, loan commitment, final walkthrough, closing. Put each one in the calendar with a reminder 3 days before AND on the day.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Send the welcome email to everyone</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Buyer/seller, both agents, lender, title, inspector. One email with the full timeline. Everyone now has the same dates, and you are visibly the person running it.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Confirm earnest money landed</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The first deadline and the most commonly missed. Get written confirmation from title/escrow — not the buyer&#x27;s word.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Chase every milestone 3 days early</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Never on the day. &quot;Just confirming the appraisal is booked for Thursday&quot; three days out is a nudge. The same message on the day is a crisis.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Log every document into the file as it arrives</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Named consistently, in the right folder. Compliance audits are real and a missing signature page is your problem.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Final walkthrough and closing confirmation</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Confirm utilities, keys, remotes, and that the seller actually removed what they said they would. Then confirm the closing time and location with everyone 24 hours ahead.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Assuming silence means progress. The lender who hasn&#x27;t replied in four days is not quietly working — something is stuck. Chase on a schedule, not on a feeling.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A deadline is about to be missed</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Saying nothing and hoping the lender comes through, then telling the agent the morning it&#x27;s due.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">A deadline missed with notice is a problem you solve with an extension addendum. A deadline missed without notice can kill the deal and cost the buyer their earnest money. The difference is entirely how early you speak up.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Heads up — loan commitment is due Friday and the lender hasn&#x27;t sent underwriting conditions. I&#x27;ve chased twice (Tues, Thurs, both logged). Recommend we request a 5-day extension today rather than Friday. Want me to draft the addendum?&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Early, evidenced, with a recommendation and an offer to do the work. Agents forgive problems. They do not forgive surprises.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Someone asks you to just sign or initial something</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Sure, I&#x27;ll initial that change for the agent, she&#x27;s on a showing.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Signing on behalf of anyone without written authority is forgery. It does not matter how small the change is or how much of a hurry everyone is in. This ends careers and licences.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I can&#x27;t sign for [agent] — I&#x27;ll get it in front of her right now. Sending to her phone via DocuSign, she signs from anywhere in 30 seconds. What time do you need it by?&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Refuses cleanly, then solves the actual problem (speed) another way. Knowing exactly where your authority stops is a senior trait, not a junior one.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Transaction deadline tracker</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One per deal. Build it the day the contract is signed. This single document is why TCs get paid double what admin VAs do.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">TRANSACTION: [address]\nContract date: [date] | Closing date: [date] | Price: $[n]\nBuyer: [name] | Seller: [name] | My side: [buyer/seller]\n\nPARTIES\nListing agent: [name, phone, email]\nBuyer agent: [name, phone, email]\nLender: [name, phone, email]\nTitle/escrow: [name, phone, email, file #]\nInspector: [name, phone]\n\nDEADLINES — reminder set 3 days before AND day of</pre><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">#</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Milestone</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Due</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Owner</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Chased</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Status</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">1</td><td class=\"px-3 py-2.5 text-ink-2\">Earnest money delivered</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Buyer</td><td class=\"px-3 py-2.5 text-ink-2\">[dates]</td><td class=\"px-3 py-2.5 text-ink-2\">✅ confirmed by title [date]</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">2</td><td class=\"px-3 py-2.5 text-ink-2\">Disclosures delivered</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Seller</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">3</td><td class=\"px-3 py-2.5 text-ink-2\">Inspection ordered</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Buyer</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">4</td><td class=\"px-3 py-2.5 text-ink-2\">Inspection completed</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Inspector</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">5</td><td class=\"px-3 py-2.5 text-ink-2\">Repair request submitted</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Buyer agent</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">6</td><td class=\"px-3 py-2.5 text-ink-2\">Repair negotiation resolved</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Both</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">7</td><td class=\"px-3 py-2.5 text-ink-2\">Appraisal ordered</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Lender</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">8</td><td class=\"px-3 py-2.5 text-ink-2\">Appraisal received</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Lender</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">9</td><td class=\"px-3 py-2.5 text-ink-2\">Loan commitment</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Lender</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">10</td><td class=\"px-3 py-2.5 text-ink-2\">Title commitment reviewed</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Title</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">11</td><td class=\"px-3 py-2.5 text-ink-2\">Insurance bound</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Buyer</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">12</td><td class=\"px-3 py-2.5 text-ink-2\">Closing disclosure issued (3 days prior!)</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Lender</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">13</td><td class=\"px-3 py-2.5 text-ink-2\">Final walkthrough</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Buyer agent</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">14</td><td class=\"px-3 py-2.5 text-ink-2\">Utilities transferred</td><td class=\"px-3 py-2.5 text-ink-2\">[date]</td><td class=\"px-3 py-2.5 text-ink-2\">Buyer</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">15</td><td class=\"px-3 py-2.5 text-ink-2\">CLOSING</td><td class=\"px-3 py-2.5 text-ink-2\">[date] [time] [place]</td><td class=\"px-3 py-2.5 text-ink-2\">All</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">DOCUMENTS RECEIVED\n[ ] Executed contract, all pages, all initials\n[ ] All addenda\n[ ] Earnest money receipt\n[ ] Seller disclosures\n[ ] Inspection report\n[ ] Repair addendum\n[ ] Appraisal\n[ ] Loan commitment letter\n[ ] Title commitment\n[ ] Final settlement statement\n\nRISK LOG\n[Anything wobbling, with the date I flagged it to the agent]</pre></div></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Contract-to-close welcome email</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Send the day the contract is executed, to every party. Sets you up as the coordinator and prevents half the chasing.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Subject: [Address] — under contract, key dates inside\n\nHi everyone,\n\nCongratulations — [address] is under contract as of [date], closing [date].\n\nI&#x27;m [name], transaction coordinator for [agent]. I&#x27;ll be keeping this file on track and chasing deadlines, so please copy me on everything.\n\nKEY DATES\n• Earnest money due: [date]\n• Inspection period ends: [date]\n• Appraisal ordered by: [date]\n• Loan commitment: [date]\n• Final walkthrough: [date]\n• CLOSING: [date] at [time], [location]\n\nWHO&#x27;S WHO\nListing agent: [name] — [email]\nBuyer agent: [name] — [email]\nLender: [name] — [email]\nTitle: [name] — [email], file #[n]\n\nWHAT I NEED FIRST\n• [Party]: [document] by [date]\n• [Party]: [document] by [date]\n\nI&#x27;ll send a short status update every [day]. If anything slips, tell me early — almost everything is fixable with notice and very little is fixable on the day.\n\n[Name]\n[phone] | [email]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build a mock contract-to-close tracker for three simultaneous fictional deals with different closing dates and one deliberate deadline collision.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A tracker sheet with the five key deadlines per deal, a document checklist, a chase schedule, and three daily status lines including one escalation.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 70 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every deadline is calculated from an effective date, not typed at random</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The document checklist names who owes each item</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The chase schedule is date-based, not vibes-based</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">One escalation is written with the risk stated and a suggested action for the agent</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is an explicit note that the VA does not handle funds</span></label></li></ul></div>"},{"n":6,"title":"Marketing the agent will not do themselves","outcome":"You can produce the recurring marketing assets a small team needs: buyer packet, listing flyer, social calendar, email drip, review workflow.","badges":["Tools","2 templates"],"minutes":34,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Agents are inconsistent marketers because marketing is never urgent. Your value is that it happens on a schedule whether they feel like it or not.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A buyer packet is the highest-leverage single asset: what to expect, the steps from offer to keys, who does what, timelines, costs, and how to reach the team. Build it once, use it forever.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The social calendar for a small team is boring on purpose. New listing, open house, just sold, market stat, neighbourhood spotlight, client review, agent face. Rotate, do not reinvent.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every marketing asset needs the brokerage&#x27;s required disclosures and logos. Ask for the brand guide and the compliance requirements in week one, because fixing 40 graphics later is horrible.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Reviews are a workflow, not a hope. Ask at the moment of maximum happiness, which is closing day, with a direct link and a two-line pre-written prompt.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Local SEO for an agent means the Google Business Profile is complete, the service areas and hours are correct, reviews get replies, and the site has a page for each neighbourhood they actually work.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Track something. Open rates, listing views, open house sign-ins. Marketing with no number attached is the first thing cut when the client tightens up.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Four weeks of the Reyes Group calendar</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Mon — Market stat graphic. One number, one sentence of context, no jargon.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Wed — Listing or neighbourhood spotlight, depending on inventory.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Fri — Client review or a just-sold post with the story, not just the price.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Sun — Open house reminder, posted 10am, boosted to a 5-mile radius if there is budget.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Monthly — Email to the full sphere: three listings, one market observation, one referral ask.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">After every closing — Review request within 24 hours, direct Google link, template text the agent sends from their own phone.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Four posts a week for a solo agent is sustainable. Two a day is a fantasy that dies in week three and makes you look unreliable.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Real estate marketing tools</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Agents will not do this themselves. Being the person who reliably produces the marketing is often how you become indispensable before you&#x27;re technically senior.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Canva</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Flyers, just-listed posts, market update graphics, open house signs.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a weekend</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier, $10/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Build a branded template set for the agent once: just listed, open house, just sold, price improvement, market update. Then it&#x27;s 5 minutes per listing forever.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">CloudCMA</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Comparative market analysis packets that look professional.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — an hour</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$30/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Turns an hour of agent work into 3 minutes. If your agent doesn&#x27;t have it, suggesting it makes you look like you know the industry.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">CapCut</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Listing walkthrough reels from the photographer&#x27;s video.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Short-form listing video massively outperforms static photos on social. Learn this and you can charge more.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">BombBomb / Loom</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Personal video emails from the agent to leads.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier / $39/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Video emails get far higher reply rates. You script and schedule; the agent just records.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Mailchimp / FUB campaigns</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Monthly market updates to the database.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The agent&#x27;s database is their most valuable asset and it&#x27;s almost always neglected. Reviving it is a fast, visible win.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Matterport / Zillow 3D</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Virtual tours.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy to publish, hardware to capture</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$10–70/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You&#x27;ll coordinate, not shoot. Know how to get the tour link into MLS and the portals correctly.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Monthly market update email</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">The single highest-ROI marketing an agent can send. Same shape monthly, so it becomes a habit for the reader.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Subject: [Area] market — [month] in 4 numbers\n\nHi [first name],\n\nHere&#x27;s what happened in [area] last month.\n\nTHE NUMBERS\nMedian sale price: $[n] ([+/-n]% vs last month, [+/-n]% vs last year)\nHomes sold: [n]\nAverage days on market: [n] ([+/-n] days)\nMonths of inventory: [n] — [under 4 = seller&#x27;s market / 4–6 = balanced / over 6 = buyer&#x27;s market]\n\nWHAT IT MEANS\n[Two sentences in plain English. Not &quot;the market remains dynamic&quot;. Something like: &quot;Homes are sitting about 9 days longer than they were in spring, and roughly a third of listings took a price cut. If you&#x27;re buying, you have more room to negotiate than you did three months ago.&quot;]\n\nNOTABLE\n• Highest sale: [address] at $[n]\n• [Anything genuinely interesting — a new development, a school change, an infrastructure project]\n\nTHINKING ABOUT MOVING?\n[Agent] does a free walkthrough valuation — no obligation, takes about 20 minutes. Just reply to this email.\n\n[Agent name]\n[Brokerage] | [licence #] | [phone]\n\n[Required brokerage disclaimer and unsubscribe]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Just-listed social caption set</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Four variations per listing so the agent&#x27;s feed isn&#x27;t identical every time.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>1. THE FEATURE LEAD\n&quot;[n] bed, [n] bath in [neighbourhood] — and that kitchen island is [n] feet long.\n$[price] | [address]\nOpen [day] [time]. Comment ADDRESS and I&#x27;ll send the full details.&quot;\n\n2. THE LIFESTYLE LEAD\n&quot;Coffee on the back deck, [n] minutes from [landmark].\nJust listed in [neighbourhood]: [n] bed, [n] bath, $[price].\nDM for a private showing.&quot;\n\n3. THE NUMBERS LEAD\n&quot;[n] sq ft. [n] beds. Built [year]. $[price].\n[Neighbourhood] hasn&#x27;t had a listing under $[n] in [n] months.\nLink in bio.&quot;\n\n4. THE HONEST LEAD (these perform best)\n&quot;It needs a new bathroom. It also has [n] sq ft, a [n]-car garage, and it&#x27;s $[n] under what the neighbours sold for.\n[Address], $[price]. Come see it [day].&quot;\n\nRULES\n• Always: address or neighbourhood, beds/baths, price, one clear CTA\n• Never: &quot;won&#x27;t last long&quot;, &quot;dream home&quot;, &quot;must see&quot; — nobody believes any of it\n• Include the brokerage name and licence number where required\n• FAIR HOUSING: describe the property, never the buyer. No &quot;perfect for families&quot;.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build the Reyes Group marketing kit: a buyer packet, one listing flyer, a 30-day social calendar with copy, one email to the sphere, and a review request workflow.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A Canva or Docs folder with all five items and a one-page note on what you would measure.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 90 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The buyer packet covers offer to keys in steps with who does what</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The social calendar has real copy, not placeholder topics</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every asset has space for brokerage branding and disclosures</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The review workflow names the trigger, the channel, and the exact words</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You named three metrics and where each one comes from</span></label></li></ul></div>"},{"n":7,"title":"Outbound calling, disposition codes and not getting blamed","outcome":"You can run a calling shift, log it correctly, and report numbers that protect you from being judged on things you do not control.","badges":["Workflow","2 templates"],"minutes":40,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Around 100 dials in a four-hour shift is a realistic load on a manual or single-line dialer. Most of it is no answer, wrong number, and a fast no. That is the job, not a failure.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Clients often quote something like a two percent success rate. Understand what they are counting before you agree to it, because &quot;success&quot; can mean a connect, a conversation, a qualified lead or a signed listing, and those differ by an order of magnitude.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You control dials, adherence to the script, tone, logging quality and follow-up discipline. You do not control the list, the offer, the market, the price or whether the agent calls the appointment back.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">So report both. Activity metrics prove you worked. Outcome metrics diagnose the campaign. Reporting only outcomes lets a client blame you for their bad list.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Disposition codes are the diagnostic. If 60 percent of the list comes back wrong number or disconnected, the data source is the problem and you now have the evidence to say so without an argument.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Compliance: work from a scrubbed list, respect do-not-call requests instantly and permanently, know the calling hours for the target state, and never mass-text from your personal number.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Objection handling is three moves. Acknowledge, ask one question, offer a low-commitment next step. Arguing with someone who said no is how you get complaints.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A calling week reported two ways</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&quot;Made about 400 calls this week. No listings yet. Sorry, hoping next week is better.&quot;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">WEEK 34 — Expired listing campaign, Hillsborough County list (PropStream pull, 22 Aug)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Dials 412 / Connects 63 (15.3%) / Conversations over 60s 21 / Qualified 6 / Appointments set 3 / Held 2</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Dispositions: No answer 214, Voicemail 98, Wrong or disconnected 37, Not interested 41, Callback 15, DNC 4, Qualified 6</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Read: 37 wrong or disconnected out of 412 is 9% dead data. Worth checking the pull filters.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Read: connect rate is best 4–6pm local, 22% vs 11% in the morning. Suggest shifting two hours.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Ask: two appointments held, neither has been followed up by the agent. Need a call-back owner.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second version cannot be used against you, and it makes the agent&#x27;s problems visible without you ever accusing them of anything.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">A calling block that doesn&#x27;t destroy you</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Every day. Same hours. Consistency beats intensity in outbound.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Prep the list before the block starts</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Never research mid-block. Have the list, the CRM open, the script visible and water on the desk. The block is for dialing only.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Call in a tight window, same time daily</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Two hours of focused dialing beats six hours of drifting. Best answer rates are typically early morning and 4–6pm their time.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Open with a question, not a pitch</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;Hi, is this [name]? ... Great — quick question, are you still looking in [area]?&quot; People hang up on statements and answer questions.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Disposition every call immediately, before the next dial</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Not at the end of the block. You will not remember call 14.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Set the next action on the record before moving on</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">No exceptions. A dialed lead with no next step is worse than an uncalled one, because now you think it&#x27;s handled.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Report the numbers daily, including the bad ones</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Dials, contacts, appointments, and your contact rate. Reporting a rough day honestly buys you credibility for the good ones.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Judging your day by appointments set. Contact rate is what you control; appointments are partly luck and list quality. Track both, but only beat yourself up about the first.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Disposition codes</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Agree these with the agent in week one and never invent new ones mid-flight. Consistent codes are the only way calling data means anything.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>EVERY CALL GETS EXACTLY ONE CODE\n\nCONTACT MADE\nAPPT-SET — appointment booked. Log date/time/type.\nHOT — wants to move in under 30 days. Notify agent same day.\nWARM — 1–3 months out. Cadence: call every 2 weeks.\nNURTURE — 3+ months out or just browsing. Monthly email, quarterly call.\nNOT-INTERESTED — said no, but not hostile. Long-term nurture, quarterly.\nDNC — asked not to be contacted. STOP IMMEDIATELY AND PERMANENTLY. Tag and never call again — this is a legal requirement, not a preference.\nALREADY-WORKING — has an agent. Note WHO and when their agreement ends.\nWRONG-NUMBER — mark the number bad, don&#x27;t delete the record.\nSOLD-BOUGHT — already transacted. Move to past-client nurture, ask for a referral.\n\nNO CONTACT\nNA-VM — no answer, voicemail left\nNA-NVM — no answer, no voicemail (mailbox full/not set up)\nBUSY — line busy\nCALLBACK — they asked you to call back. LOG THE EXACT TIME.\nBAD-NUM — disconnected or invalid\n\nDAILY NUMBERS TO REPORT\nDials: [n]\nContacts (a human spoke): [n]\nContact rate: [contacts ÷ dials]% ← this is the number you control\nAppointments set: [n]\nConversion: [appts ÷ contacts]%\n\nBENCHMARKS (rough, list quality changes everything)\nContact rate 8–15% on cold lists, 25–40% on inbound leads\nAppointment rate 5–10% of contacts on cold, 15–25% on inbound\nIf your contact rate is under 5%, the LIST is the problem, not you. Say so.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Objection responses</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Learn the shape, not the words. Read verbatim and you sound like a robot, which is worse than saying nothing.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>&quot;I&#x27;M NOT INTERESTED&quot; (said in the first 5 seconds — this is a reflex, not an answer)\n&quot;Totally fair, you don&#x27;t know me yet. Can I ask one thing — are you still looking in [area], or has that changed?&quot;\n\n&quot;I&#x27;M JUST BROWSING / NOT READY YET&quot;\n&quot;That&#x27;s the smart way to do it. When you say not ready — is that a few months, or more like next year? I ask because [area] moves differently depending, and I&#x27;d rather send you useful stuff than nothing.&quot;\n\n&quot;I ALREADY HAVE AN AGENT&quot;\n&quot;Good, I won&#x27;t step on that. Who are you working with? ... Great, [name]&#x27;s solid. I&#x27;ll take you off our list — if anything changes, we&#x27;re here.&quot;\n(Then actually take them off. Poaching is an ethics complaint.)\n\n&quot;HOW DID YOU GET MY NUMBER?&quot;\n&quot;You filled in a form on [site] on [date] looking at [address] — that comes through to us. If that wasn&#x27;t you or you&#x27;d rather I didn&#x27;t call, say the word and I&#x27;ll remove you right now.&quot;\n(Always be able to answer this precisely. If you can&#x27;t, the list is a problem.)\n\n&quot;JUST EMAIL ME THE INFO&quot;\n&quot;Will do — what&#x27;s the best address? And so I send the right thing rather than everything: are you leaning [X] or [Y]?&quot;\n(Get one qualifying answer before you let the call end.)\n\n&quot;WHAT&#x27;S MY HOUSE WORTH?&quot;\n&quot;I can&#x27;t give you a number — I&#x27;m not licensed and a guess would do you no favours. [Agent] does a proper walkthrough valuation for free, about 20 minutes. She&#x27;s got [day] at [time] or [day] at [time] — which is easier?&quot;\n\n&quot;I NEED TO TALK TO MY [SPOUSE]&quot;\n&quot;Makes sense. When are you two likely to talk about it? ... I&#x27;ll call back [day after that]. Anything I can send over in the meantime that&#x27;d help the conversation?&quot;\n\nUNIVERSAL RULES\n• Never argue. Agree with the feeling, then ask a question.\n• Two attempts to redirect, maximum. A third makes you the villain.\n• End every call with a next step or a clean, cheerful exit.\n• The moment they say stop — stop. Warmly. Permanently.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write a call script for an expired listing campaign with three objection branches, build a disposition code list, and produce a fictional weekly call report using invented but internally consistent numbers.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Script, disposition list, one-page weekly report with an activity block, an outcome block, and two written reads.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 65 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The script opens with who you are and why you are calling in under 12 seconds</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every objection branch ends with a question or a low-commitment offer</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Disposition codes are exclusive and cover every possible call end</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The report separates activity from outcomes</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You wrote at least one read that puts responsibility on the data or the process, politely</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a do-not-call handling rule</span></label></li></ul></div>"},{"n":8,"title":"Capstone: run the Reyes Group","outcome":"You leave with a portfolio built around one seat, not a scattering of samples that make you look like a generalist.","badges":["Rates","2 templates"],"minutes":90,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pick one capstone: the lead engine (CRM plus nurture plus calling) or the coordination desk (listing launch plus contract to close). Do one properly rather than both badly.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every artefact needs a one-line note on the decision behind it. Anyone can copy a checklist template. Explaining why the HOA estoppel goes on the board first is what proves you understand the work.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write the escalation rules as a standalone page. What you decide alone, what you flag, what you never touch. Agents read that page and relax.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Record a three-minute Loom clicking through the CRM or the transaction board. Real estate clients are impatient readers and fast hirers.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The two capstone packs</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">LEAD ENGINE — CRM schema with stage definitions, cleanup log, speed-to-lead SOP, two five-touch sequences, call script, disposition list, weekly call report, monthly pipeline dashboard, escalation rules.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">COORDINATION DESK — Listing intake form, seller prep list, launch timeline, listing QA checklist, buyer packet, contract-to-close tracker for three deals, document chase schedule, daily status lines, escalation rules.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">BOTH — A one-page index, a note that all names, addresses and data are fictional, and a three-minute Loom.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Nine or ten files in one Drive folder with a clean index. Share the link in the first line of your application, not as an attachment nobody opens.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Pricing yourself once you can run the Reyes Group</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">What each capability adds. The point of stacking them is that a team paying $6/hr for admin will pay double for the same person doing TC work.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Admin + CRM only</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$5–7</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$850–1,150</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Your floor. Never stay here past a year.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">+ Listing coordination</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$6–9</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,000–1,450</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">First real step up. Learnable in a month.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">+ Lead follow-up / ISA</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$7–11 + bonus</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,150–1,800 + bonus</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You now touch revenue directly, so ask for a piece of it.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">+ Transaction coordination</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$9–14</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,500–2,300</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The biggest single jump. Or price per file: $250–500 each.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Full ops lead for a team</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$13–20</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,100–3,200</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You run the systems and the other VAs. Agent stops thinking about operations entirely.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Stack capabilities one at a time and renegotiate each time you add one. Waiting for an agent to notice you&#x27;ve grown is how three years pass at the same rate.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Real estate VA portfolio one-pager</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Agents skim. Lead with the systems you built, because that&#x27;s what they can&#x27;t build themselves.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[YOUR NAME] — Real Estate VA\n[email] | [phone] | Works [hours] EST/PST | [portfolio link]\n\nWHAT I RUN\nCRM: Follow Up Boss, kvCORE | TC: Dotloop, SkySlope | Marketing: Canva, CloudCMA, CapCut\nTimezone: I work US hours. [Specific hours you commit to.]\n\nWORKED EXAMPLE — THE REYES GROUP (practice scenario, not a paid client)\nA 3-agent team with 400 CRM records nobody trusted, 3 active listings and 5 deals in flight.\n\nWhat I built:\n1. CRM cleanup + tagging system — 400 records audited, 63 duplicates merged, every record given a next action [link]\n2. 30-day, 8-touch lead follow-up cadence with scripts [link]\n3. Listing launch checklist — 20 steps, fair-housing screened [link]\n4. Transaction deadline tracker — 15 milestones, chased 3 days early [link]\n5. Disposition code system + daily calling report [link]\n6. Monthly market update email template [link]\n\nWHAT I KNOW I CAN&#x27;T DO\nI&#x27;m not licensed. I don&#x27;t give valuations, advise on offers, or negotiate. I route those to the agent fast and cleanly — and I know exactly where that line is, which is the part that protects your licence.\n\n3-minute walkthrough of the deadline tracker: [Loom link]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Daily huddle note to the agent</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Send at the end of every shift. Five lines. This is the habit that turns a VA into an indispensable one.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[Date] — EOD\n\nDEALS\n[Address] — [status]. [What moved or what&#x27;s stuck.]\n[Address] — [status]. [What moved or what&#x27;s stuck.]\n\n⚠ NEEDS YOU\n• [Thing only you can do] — by [date]\n• [Decision needed] — [the options, and what I&#x27;d recommend]\n\nCALLS\nDials [n] | Contacts [n] ([n]%) | Appts set [n]\nBooked: [name] — [day/time] — [buyer/seller, area]\n\nLISTINGS\n[Address] — [n] showings this week, feedback summary sent to seller\n\nTOMORROW\n[What I&#x27;m picking up first]\n\nNothing on fire. / One thing on fire: [what].</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Assemble your chosen pack from modules 2 to 7 for the fictional Reyes Group, write the index and the escalation rules page, and record the Loom.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A public-view folder link you can paste into any application.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 90 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Everything is clearly labelled as simulated work with fictional addresses</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No MLS data, no real client information, no real phone numbers</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The escalation rules page distinguishes decide, flag, and never touch</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The index reads in the order a hiring agent cares about</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The Loom is under four minutes and shows the board or CRM in motion</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You opened the share link in a private window to check permissions</span></label></li></ul></div>"}],"quiz":[{"q":"A buyer enquiry lands at 2:14am your time on a listing. Your shift starts at 7am. What is the correct setup?","options":["Respond when you start your shift, five hours is fine","An agreed auto-response goes out instantly, and you make the human contact as the first task of your shift","Wake up and call, speed to lead is everything","Leave it in the queue for the agent, they're in that time zone"],"answer":1,"explain":"Speed to lead matters, but heroics you cannot sustain are worse than a system. Agree an instant automated acknowledgement plus a human touch at a guaranteed time, and put it in the SOP so nobody is surprised."},{"q":"You are deduplicating 8,000 CRM records. What is your first action?","options":["Merge everything matching on first and last name","Export a dated backup before touching anything","Delete every record with no phone number","Standardise the tags so the merge is cleaner"],"answer":1,"explain":"Bulk operations in a CRM are frequently irreversible. Export first, work on a copy, verify a sample, then import. Also, never match duplicates on name alone."},{"q":"The inspection objection deadline is Tuesday 5pm and the report has not arrived. What do you do?","options":["Email the agent Wednesday with an update","Ask the buyer's agent for an extension yourself","Flag it to the agent now with the deadline, what you have already chased, and a suggested next step","Assume it is coming, these usually land in time"],"answer":2,"explain":"Escalate before the deadline, with the chase history and an option attached. Requesting a contract extension is a negotiation, which is the agent's call, not yours."},{"q":"Your week's dispositions show 37 wrong or disconnected numbers out of 412 dials. What is the right move?","options":["Nothing, that is normal attrition","Quietly stop logging them so the report looks better","Put it in the weekly report as a 9% dead-data rate and suggest checking the pull filters","Ask the agent for a bigger list to compensate"],"answer":2,"explain":"Dispositions exist to diagnose. Reporting the dead-data rate is how you improve the campaign and, incidentally, how you stop being blamed for a list you did not build."},{"q":"Which listing description line is a fair housing problem?","options":["Four bedrooms with a converted attic office","Walking distance to a quiet family church, great for families","New roof in 2024, HVAC serviced March 2026","Corner lot, 0.24 acres, fenced rear yard"],"answer":1,"explain":"Describe the property, never the ideal occupant. References to family status, religion, or 'safe' neighbourhoods create real complaints, and the agent will not be the one who typed it."},{"q":"The client asks you to email the buyer the escrow wiring instructions because they are in a showing.","options":["Send it, you have the PDF","Send it but add a warning about fraud","Decline and explain that wiring instructions only ever go from the title company, verified by phone","Forward the original email from the title company instead"],"answer":2,"explain":"Wire fraud in real estate is enormous and email is the attack surface. A VA never sends, forwards or confirms payment details. This is one of the very few hard no's in the job."}],"glossary":[{"term":"MLS","def":"The multiple listing service for a market. Access is licensed and rule-bound, so never use borrowed credentials."},{"term":"ISA","def":"Inside sales agent. The seat that chases, qualifies and books appointments rather than closing deals."},{"term":"TC","def":"Transaction coordinator. Runs the paperwork and deadlines from signed contract to closing."},{"term":"CMA","def":"Comparative market analysis. You can assemble the comps, the licensed agent gives the number."},{"term":"SOI","def":"Sphere of influence. Everyone the agent already knows. The cheapest source of business and the most neglected."},{"term":"FSBO","def":"For sale by owner. A seller marketing without an agent, and a standard prospecting list."},{"term":"Expired listing","def":"A listing whose agreement ended without selling. The other standard prospecting list."},{"term":"Speed to lead","def":"Time between an enquiry arriving and a real human responding. Measured in minutes, not hours."},{"term":"Disposition","def":"The result code you log for a call or lead. The pattern across dispositions diagnoses the campaign."},{"term":"Drip campaign","def":"A timed sequence of messages sent automatically over days or weeks."},{"term":"Nurture","def":"Planned long-term follow-up for someone who is real but not ready."},{"term":"DNC","def":"Do not call. A permanent, immediate, no-exceptions removal from every calling list."},{"term":"TCPA","def":"US legislation restricting autodialled calls and texts. Your client is responsible for compliance, but you need to know it exists."},{"term":"EMD","def":"Earnest money deposit. A transaction milestone you confirm and track, never handle."},{"term":"Estoppel","def":"An HOA document confirming fees and status. Slow to arrive, and a common cause of closing delays."},{"term":"Contingency","def":"A condition that lets a party exit the contract. Each one has a deadline, and deadlines are your job."},{"term":"Skip trace","def":"Finding current contact details for a property owner. Data quality varies enormously by provider."},{"term":"Fair housing","def":"Rules on how property can be advertised. Describe the property, never the ideal buyer."}]} as DeepCourse;

export default course;
